// C — valida somente vagas filtradas; nunca declara ACTIVE por HTTP 200 isolado.
const envelope=$input.first().json||{};
const jobs=Array.isArray(envelope.jobs)?envelope.jobs:[];
const blockedHost=host=>{
 const h=String(host||'').toLowerCase();
 if(['localhost','127.0.0.1','0.0.0.0','::1','169.254.169.254'].includes(h))return true;
 if(/(\.local|\.localhost|\.internal)$/.test(h))return true;
 if(/^\d+\.\d+\.\d+\.\d+$/.test(h)){
  const parts=h.split('.').map(Number);
  if(parts.some(x=>x>255))return true;
  const [a,b]=parts;
  return a===0||a===10||a===127||a>=224||a===169&&b===254||a===192&&b===168||a===172&&b>=16&&b<=31||a===100&&b>=64&&b<=127;
 }
 return h.includes(':'); // IPv6 literal: bloquear
};
function safeUrl(value){
 try{
  const u=new URL(String(value||''));
  if(u.protocol!=='https:'||u.username||u.password||blockedHost(u.hostname))return null;
  return u.href;
 }catch{return null;}
}
const history=[...(envelope.previous?.vagas||[]),...(envelope.previous?.historicoVagas||[])];
const selectedIds=new Set(jobs.map(j=>String(j.id)));
const cutoff=Date.now()-23*60*60*1000;
const verifyLimit=Math.max(0,Math.min(50,Number(envelope.profile?.historyVerificationLimit??30)));
const candidates=history.filter(job=>{
 if(!job?.id||selectedIds.has(String(job.id)))return false;
 const status=job.statusCandidatura||job.application_status||'PENDING_VALIDATION';
 if(['CLOSED','EXPIRED'].includes(status))return false;
 const latest=Date.parse(job.last_verified_at||job.ultimaVerificacaoCandidatura||'');
 return !Number.isFinite(latest)||latest<cutoff;
}).slice(0,verifyLimit);
const all=[...jobs,...candidates];
if(!all.length)return [{json:{skip:true}}];
return all.map((job,index)=>{
 const official=safeUrl(job.link||job.source_url||job.application_url);
 let checkedUrl=official,validationKind='html';
 if(official){
  const match=/^https:\/\/github\.com\/([^/?#]+)\/([^/?#]+)\/issues\/(\d+)\/?(?:\?.*)?$/i.exec(official);
  if(match){
   checkedUrl='https://api.github.com/repos/'+encodeURIComponent(match[1])+'/'+encodeURIComponent(match[2])+'/issues/'+match[3];
   validationKind='github_issue';
  }
 }
 if(validationKind==='html'&&String(job.fonte||job.source||'').toLowerCase().includes('himalayas')){
  const identifiers=[job.guid,job.external_id,job.id,job.link,job.source_url,job.urlNormalizada];
  for(const candidate of identifiers){
   const match=/https:\/\/himalayas\.app\/companies\/([a-z0-9-]+)\/jobs\/([a-z0-9-]+)/i.exec(String(candidate||''));
   if(match){
    checkedUrl='https://himalayas.app/jobs/api/companies/'+match[1]+'/jobs/'+match[2];
    validationKind='himalayas_job';
    break;
   }
  }
 }
 return {json:{job,index,originalUrl:official,checkedUrl,validationKind}};
});

// C — interpreta evidências conservadoramente e devolve envelope único.
const envelope=$('Entrada C').first().json||{};
const checked=$input.all();
const prepared=$('Preparar verificações').all();
const original=prepared.filter(p=>!p.json.skip).map(p=>p.json.job);
const now=new Date().toISOString();
const closedRe=/(vaga|oportunidade|position|job|application|candidatura).{0,80}(encerrad[oa]|fechad[oa]|expirad[oa]|preenchid[oa]|nao est[aá] mais dispon[ií]vel|n[aã]o aceita mais candidaturas|no longer accepting|no longer available|position has been filled|job has been filled|applications are closed|this role is closed|job expired)/i;
const expiredRe=/(prazo|deadline|application deadline|data limite).{0,60}(expirad[oa]|encerrad[oa]|passad[oa]|closed|expired)|application deadline has passed/i;
const applyControlRe=/<form\b[^>]*(apply|application|candidatur)|<(button|a|input)\b[^>]*(apply|application|candidatur|candidate)|\b(apply now|apply for this job|apply for position|candidatar-se|candidate-se|enviar candidatura|inscreva-se)\b/i;

const results=[];
for(let i=0;i<original.length;i++){
 const p=prepared[i]?.json||{}, r=checked[i]?.json||{}, job=original[i];
 const status=Number(r.statusCode||r.status||r.body?.statusCode||0);
 const body=typeof r.body==='string'?r.body:typeof r.data==='string'?r.data:JSON.stringify(r.body||r.data||'');
 let apiData=null;
 if(p.validationKind==='github_issue'||p.validationKind==='himalayas_job'){
  try{const parsed=r.body??r.data??null;apiData=typeof parsed==='string'?JSON.parse(parsed):parsed;}
  catch{apiData=null;}
 }
 let state='PENDING_VALIDATION', reason='Sem confirmação explícita na página original.';
 if(!p.checkedUrl){state='PENDING_VALIDATION';reason='URL inválida ou não HTTPS; não foi possível verificar.';}
 else if(status===410&&p.validationKind==='himalayas_job'){
   state='CLOSED';reason='API oficial Himalayas confirmou encerramento do anúncio (HTTP 410).';
 }
 else if(status===404||status===410){state='SOURCE_UNAVAILABLE';reason='Fonte retornou HTTP '+status+'; não comprova encerramento.';}
 else if(!status||[401,403,429].includes(status)||status>=500){
   state='SOURCE_UNAVAILABLE';reason=status?'Fonte indisponível ou restrita (HTTP '+status+').':'Erro de rede ou timeout.';
 }else if(status>=200&&status<300){
   const expiry=Date.parse(job.expiraEm||job.deadline||'');
   if(p.validationKind==='himalayas_job'){
     if(apiData?.job&&typeof apiData.job==='object'){
       state='ACTIVE';reason='API oficial Himalayas confirmou anúncio ativo (HTTP 200 com job); candidatura final depende do link applicationLink.';
     }else{
       state='PENDING_VALIDATION';reason='API Himalayas respondeu sem objeto job; anúncio não confirmado.';
     }
   }else if(p.validationKind==='github_issue'){
     if(apiData?.pull_request){
       state='PENDING_VALIDATION';reason='Item da API é pull request, não anúncio de vaga.';
     }else if(apiData?.state==='closed'){
       state='CLOSED';reason='Anúncio encerrado: issue fechada na API oficial do GitHub; candidatura externa não verificada.';
     }else if(apiData?.state==='open'){
       state='PENDING_VALIDATION';reason='Issue aberta no GitHub. A existência da publicação não comprova inscrições abertas.';
     }else{
       state='PENDING_VALIDATION';reason='Resposta da API GitHub sem estado inequívoco da issue.';
     }
   }else if(Number.isFinite(expiry)&&expiry<Date.now()){
     state='EXPIRED';reason='Prazo explícito de inscrição expirado.';
   }else if(expiredRe.test(body)||closedRe.test(body)){
     state='PENDING_VALIDATION';
     reason='Texto da página sugere encerramento, mas sem status estruturado inequívoco; revisão manual necessária.';
   }
   else if(/<form\\b[^>]*[\\s\\S]{0,1500}(?:apply|application|candidatur)/i.test(body)){
     state='PENDING_VALIDATION';reason='Formulário encontrado, mas aceitação de inscrições não pôde ser comprovada de forma automática.';
   }else{state='PENDING_VALIDATION';reason='Página acessível, inscrições não confirmadas.';}
 }else{state='PENDING_VALIDATION';reason='Resposta HTTP '+status+' não conclusiva.';}
 results.push({...job,statusCandidatura:state,application_status:state,
   ultimaVerificacaoCandidatura:now,last_verified_at:now,
   motivoVerificacaoCandidatura:reason,httpStatusVerificacao:status||null,
   urlVerificada:p.originalUrl||p.checkedUrl||null});
}
return [{json:{...envelope,jobs:results,validationStats:{
checked:results.length,counts:results.reduce((a,j)=>(a[j.statusCandidatura]=(a[j.statusCandidatura]||0)+1,a),{})
},validatedAt:now}}];

const rows=$input.all();
return rows.map(item=>{
 const j=item.json, code=Number(j.statusCode||j.status||0);
 const err=Boolean(j.error)||j.body?.error==='ETIMEDOUT';
 const transient=code===429||code===408||code>=500||err||code===0;
 const attempts=Number(j.attempt||0);
 const shouldRetry=transient&&Boolean(j.checkedUrl)&&attempts<3;
 const next=attempts+1;
 const retryAfter=Number(j.headers?.['retry-after']||j.headers?.['Retry-After']||NaN);
 const delay=Number.isFinite(retryAfter)&&retryAfter>0?
   Math.min(120,retryAfter):Math.min(60,2*Math.pow(2,attempts));
 return {json:{...j,attempt:next,shouldRetry,retryDelaySeconds:delay,
   isTransientError:transient,validationHttpStatus:code}};
});
